    self.tp, self.reg = tp, reg

class Cond:
  # labA, labB are lists of branch targets for when the result is true or false
  def __init__(self, cond, left, right):
    self.tp, self.cond, self.left, self.right = Bool, cond, left, right
    self.labA, self.labB = [], []
