def factor():
  if SC.sym == IDENT:
    x = find(SC.val)
    if type(x) == Var:
      x = CG.genVar(x)
      getSym()
    elif type(x) == Const:
      x = Const(x.tp, x.val)
      x = CG.genConst(x)
      getSym()
    else:
