def eval(e, env):
  if type(e) in (int, bool):
    return e
  elif type(e) == Call:
    if e.name in env:
      if type(env[e.name]) in {int, bool}:
        return env[e.name]
      else:
        par, body = env[e.name]
        env2 = env.copy()
        env2.update(zip(par, [eval(a, env) for a in e.args]))
        return eval(body, env2)
    else:
      error('identifier not defined')
  elif type(e) == Unary:
    if e.op == MINUS:
      return -eval(e.operand, env)
    elif e.op == NOT:
      return not eval(e.operand, env)
    else:
      assert False
  elif type(e) == Binary:
    l, r = eval(e.left, env), eval(e.right, env)
    if e.op in (DIV, MOD, TIMES, PLUS, MINUS, LT, GT, LE, GE):
      if e.op == DIV:
        return l // r
      elif e.op == MOD:
        return l % r
      elif e.op == TIMES:
        return l * r
      elif e.op == PLUS:
        return l + r
      elif e.op == MINUS:
        return l - r
      elif e.op == LT:
        return l < r
      elif e.op == GT:
        return l > r
      elif e.op == LE:
        return l <= r
      elif e.op == GE:
        return l >= r
    elif e.op in (AND, OR):
      if e.op == AND:
        return l and r
      elif e.op == OR:
        return l or r
    elif e.op in (EQ, NEQ):
      if e.op == EQ:
        return l == r
      elif e.op == NEQ:
        return l != r
    else:
      assert False
  elif type(e) == If:
    if eval(e.cond, env):
      return eval(e.th, env)
    else:
      return eval(e.el, env)
  elif type(e) == Let:
    env2 = env.copy()
    env2.update({e.name: (e.par, e.body)})
    return eval(e.scope, env2)
  else:
    assert False
