  # list of newly created ident in tuples
  newIdents = []
  if SC.sym == IDENT:
    tid = [SC.val]
    getSym()
  else:
    mark('identifier expected')
  while SC.sym == COMMA:
    getSym()
    if SC.sym == IDENT:
      tid.append(SC.val)
