    getSym()
  else:
    mark("':' expected")
  tp = typ().val
  for i in tid:
    newDecl(i, Var(tp))
    # add the tuple to the result list
    newIdents.append((i, tp))
  while SC.sym == COMMA:
    getSym()
    if SC.sym == IDENT:
      tid = [SC.val]
      getSym()
    else:
