PlainChars = (
  ' !"#$%&\',-./0123456789:;<=>@ABCDEFGHIJKLMNO'
  + 'PQRSTUVWXYZ[]^_`abcdefghijklmnopqrstuvwxyz{}~'
)
EscapedChars = '()*+?\\|'
FirstFactor = PlainChars + '\\('

def nxt():
  global pos, sym
  if pos < len(src):
    sym, pos = src[pos], pos + 1
  else:
    sym = chr(0)

def repeat(e, n):
  if n == 0:
    return ''
  elif n == 1:
    return e
  else:
    return Conc(e, repeat(e, n - 1))

def expression():
  e = term()
  while sym == '|':
    nxt()
    e = Choice(e, term())
  return e

def term():
  e = factor()
  while sym in FirstFactor:
    e = Conc(e, factor())
  return e

