  while sym == '|':
    nxt()
    e = Choice(e, term())
  return e

def term():
  e = factor()
  while sym in FirstFactor:
    e = Conc(e, factor())
  return e

def factor():
  e = atom()
  if sym == '*':
    nxt()
    e = Star(e)
  elif sym == '+':
    nxt()
    e = Conc(e, Star(e))
  elif sym == '?':
    nxt()
    e = Choice(e, '')
  elif sym == '⁰':
    nxt()
    e = repeat(e, 0)
  elif sym == '¹':
    nxt()
    e = repeat(e, 1)
  elif sym == '²':
    nxt()
    e = repeat(e, 2)
  elif sym == '³':
    nxt()
    e = repeat(e, 3)
  return e

def atom():
  if sym in PlainChars:
    e = sym
    nxt()
  elif sym == '\\':
    nxt()
    if sym in EscapedChars:
      e = sym
      nxt()
    else:
      raise Exception('invalid escaped character at ' + str(pos))
  elif sym == '(':
    nxt()
    e = expression()
    if sym == ')':
      nxt()
    else:
      raise Exception("')' expected at " + str(pos))
  else:
    raise Exception('invalid character at ' + str(pos))
  return e

def parse(s: str):
  global src, pos
  src, pos = s, 0
  nxt()
  e = expression()
  if sym != chr(0):
    raise Exception('unexpected character at ' + str(pos))
  return e
