    try:
      return findInClass(name)
    except:
      # print("did not find in attributes")
      return findMethod(name)
  return Const(None, 0)

# return a Proc type
def findMethod(name):
  # e.g.   j.setPrintSIN
  nameSplit = name.split('.')
  if len(nameSplit) != 2:
    mark('undeinfed class identifier' + name)
  varName = nameSplit[0]  # e.g. j
  metName = nameSplit[1]  # e.g. setPrinSIN
  for l in symTab:
    found = False
    for e in l:
      if e.name == varName:
        found = True
        cl = e.tp
        assert type(cl) == Class
        break
    if found:
      break
  if not found:
    mark('undefined object identifier' + varName)
  while True:
    # class.methodName
    procName = cl.name + '.' + metName
    for l in symTab:
      for e in l:
        if procName == e.name:
          assert type(e) == Proc
          return e
    # if not found, might be base class method
    found = False
    for l in symTab:
      for e in l:
        if cl.extends == e.name:
          assert type(e) == Class
          cl = e
          found = True
          break
      if found:
        break
    if not found:
      mark('Method not found ' + name)

# return a Var type
def findInClass(name):
  #'student.grade'
  nameSplit = name.split('.')
  if len(nameSplit) != 2:
    mark('undeinfed class identifier' + name)
  varName = nameSplit[0]
  class_att_met = nameSplit[1]
  for l in symTab:
    for e in l:
      # found the Var type
      if varName == e.name:
        objAdr = e.adr
        objLev = e.lev
        objTp = e.tp
        objReg = e.reg
        for attrib in objTp.att:
          # found the tuple (name, type, offset)
          if attrib[0] == class_att_met:
            tp = attrib[1]
            offset = attrib[2]
            vari = Var(tp)
            vari.lev = objLev
            vari.name = name
            if type(objAdr) == str:
              try:
                assert '_' in objAdr
              except:
                print('Str type objAdr, but no _:', objAdr)
                mark('Str type objAdr, but no _:' + objAdr)
              vari.adr = objAdr + '+' + str(offset)
            else:
              try:
                assert type(objAdr) == int
              except:
                print('Str type objAdr, but no _:', type(objAdr))
                mark('objAdr not int type' + str(objAdr))
              vari.adr = objAdr + offset
            vari.reg = objReg
            return vari
  mark('undefined identifier' + name)

def openScope():
  symTab.insert(0, [])

def topScope():
  return symTab[0]

def closeScope():
  symTab.pop(0)

